test("partial hour rounds up", function () {
  var actual = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 10:01" });
  assert.equal(actual.status, "ok");
  assert.equal(actual.elapsedMinutes, 121);
  assert.equal(actual.roundedHours, 3);
  assert.equal(actual.billableHours, 3);
  assert.deepEqual(actual.flags, []);
});

test("real time across spring-forward keeps exact hours", function () {
  var actual = code.billableObservationHours({ admission: "2026-03-07 22:00", discharge: "2026-03-08 22:00" });
  assert.equal(actual.status, "ok");
  assert.equal(actual.elapsedMinutes, 1380);
  assert.equal(actual.roundedHours, 23);
  assert.equal(actual.billableHours, 23);
  assert.deepEqual(actual.flags, []);
});

