test("ambiguous local time on admission", function () {
  var actual = code.billableObservationHours({ admission: "2026-11-01 01:30", discharge: "2026-11-01 03:00" });
  assert.equal(actual.status, "ambiguous");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.match(actual.flags.join(" "), /admission/);
});

